import { CATEGORY_ICON_DATA } from './categoryIconData.generated'

export interface CategoryIconEntry {
  /** The value of `Category.icon`. */
  name: string
  label: string
  keywords: readonly string[]
}

/**
 * Every Material icon available on both clients (generated by `task icons:generate` into
 * `design/category-icons.json`, the shared source of the admin and mobile catalogues), the
 * curated ones first with their French label and search words.
 */
export const CATEGORY_ICON_CATALOG: readonly CategoryIconEntry[] = CATEGORY_ICON_DATA.map(
  ([name, label, keywords]) => ({ name, label, keywords }),
)

/** Lower case, no accents, « œ » as « oe », dashes and underscores as spaces: « Épargne » and « epargne » are one word. */
export const normalizeSearch = (text: string): string =>
  text
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/œ/gi, 'oe')
    .replace(/[-_]+/g, ' ')
    .toLowerCase()
    .trim()

const BY_NAME = new Map(CATEGORY_ICON_CATALOG.map((entry) => [entry.name, entry]))

export const findCategoryIcon = (name: string | null | undefined): CategoryIconEntry | undefined =>
  BY_NAME.get(typeof name === 'string' ? name.trim().toLowerCase() : '')

interface Indexed {
  entry: CategoryIconEntry
  label: string
  keywords: string
  name: string
}

let index: Indexed[] | null = null

const searchIndex = (): Indexed[] => {
  index ??= CATEGORY_ICON_CATALOG.map((entry) => ({
    entry,
    label: normalizeSearch(entry.label),
    keywords: entry.keywords.map(normalizeSearch).join(' | '),
    name: normalizeSearch(entry.name),
  }))

  return index
}

/** 0 = label starts with the word, 1 = label contains it, 2 = a keyword does, 3 = the English name does; null = no match. */
const rank = (item: Indexed, words: string[]): number | null => {
  let worst = 0
  for (const word of words) {
    let best: number | null = null
    if (item.label.startsWith(word)) best = 0
    else if (item.label.includes(word)) best = 1
    else if (item.keywords.includes(word)) best = 2
    else if (item.name.includes(word)) best = 3
    if (best === null) return null
    worst = Math.max(worst, best)
  }

  return worst
}

/**
 * The icons whose label, French keywords or English name contain every word of the query, best
 * matches first (catalogue order within a rank); all of them for a blank query.
 */
export const filterCategoryIcons = (query: string): readonly CategoryIconEntry[] => {
  const words = normalizeSearch(query).split(/\s+/).filter(Boolean)
  if (words.length === 0) {
    return CATEGORY_ICON_CATALOG
  }

  const ranked: Array<{ entry: CategoryIconEntry; rank: number }> = []
  for (const item of searchIndex()) {
    const r = rank(item, words)
    if (r !== null) ranked.push({ entry: item.entry, rank: r })
  }

  return ranked.sort((a, b) => a.rank - b.rank).map((r) => r.entry)
}
